<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';import {api} from '../api';import {useWorkspace,type WorkTab} from '../stores';
const props=defineProps<{tab:WorkTab}>(),work=useWorkspace();const canCreate=ref(false),departments=ref<any[]>([]),loading=ref(false),error=ref(''),search=ref(''),inactive=ref(false);
async function load(){loading.value=true;error.value='';try{const d=await api('department-work');departments.value=d.departments;canCreate.value=d.organizationCapabilities.create;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
const filtered=computed(()=>departments.value.filter(d=>(inactive.value||d.status==='active')&&[d.code,d.name,d.description].some(v=>String(v||'').toLowerCase().includes(search.value.trim().toLowerCase()))));
function open(d:any){const tab=work.open('department-detail','',d.id);tab.title='部門 · '+d.name;}
watch(()=>work.organizationRevision,()=>{void load();});onMounted(load);
</script><template><header class="page-heading"><div><p class="eyebrow">組織與門市 / 部門管理</p><h1>部門管理</h1></div><div class="filters"><button :disabled="loading" @click="load">重新載入</button><button v-if="canCreate" class="primary" @click="work.open('organization-editor')">新增部門</button></div></header><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="loading" role="status">載入部門…</p><div class="filters"><label>搜尋部門<input v-model="search" placeholder="代碼、名稱或說明"></label><label class="check"><input type="checkbox" v-model="inactive">包含停用部門</label></div><p>{{filtered.length}} 個部門</p><div class="table-wrap"><table><thead><tr><th>部門</th><th>主管</th><th>直接成員</th><th>狀態</th><th>操作</th></tr></thead><tbody><tr v-for="d in filtered" :key="d.id"><td><strong>{{d.name}}</strong><small>{{d.code}}</small></td><td>{{d.managers.map((m:any)=>m.user?.full_name||m.user?.email).join('、')||'尚未設定'}}</td><td>{{d.members.length}} 位</td><td>{{d.status==='active'?'啟用':'停用'}}</td><td><button @click="open(d)">開啟部門</button></td></tr></tbody></table></div><p v-if="!loading&&!filtered.length">{{departments.length?'沒有符合條件的部門':'尚未建立部門，請由公司組織新增部門單位。'}}</p></template><style scoped>.filters{display:flex;gap:20px;flex-wrap:wrap;margin:24px 0;align-items:end}label{display:grid;gap:8px}.filters>label:first-child{min-width:240px;flex:1}.check{display:flex;align-items:center;padding:12px}.check input{width:18px;height:18px;min-width:18px;min-height:18px}.table-wrap{overflow:auto}table{min-width:650px}small{display:block;color:var(--muted);margin-top:6px}</style>
